<?php
session_start(); include('check-login.php'); include('dbstring.php'); include_once('department-result-workflow-utils.php');
if(!drw_is_admin()){ http_response_code(403); exit('Administrator access required.'); } drw_ensure_tables($con); $msg=''; $actor=isset($_SESSION['USERID'])?$_SESSION['USERID']:'';
function dtm($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if(isset($_POST['change_hod'])){ $d=mysqli_real_escape_string($con,$_POST['departmentid']);$h=mysqli_real_escape_string($con,$_POST['hodid']);$u=mysqli_real_escape_string($con,$actor);$ok=mysqli_query($con,"UPDATE tbldepartment SET hodid='$h',updatedat=NOW() WHERE departmentid='$d' LIMIT 1");if($ok){mysqli_query($con,"INSERT IGNORE INTO tbldepartmentteacher(departmentid,teacherid,assignedat,assignedby) VALUES('$d','$h',NOW(),'$u')");$msg='HOD updated successfully.';} }
if(isset($_POST['remove_teacher'])){ $d=mysqli_real_escape_string($con,$_POST['departmentid']);$t=mysqli_real_escape_string($con,$_POST['teacherid']);$r=mysqli_query($con,"SELECT hodid FROM tbldepartment WHERE departmentid='$d' LIMIT 1");$row=$r?mysqli_fetch_assoc($r):null;if($row&&$row['hodid']===$_POST['teacherid'])$msg='Choose a new HOD before removing the current HOD.';elseif(mysqli_query($con,"DELETE FROM tbldepartmentteacher WHERE departmentid='$d' AND teacherid='$t' LIMIT 1"))$msg='Teacher removed from department.';}
$teachers=array();$r=mysqli_query($con,"SELECT userid,CONCAT_WS(' ',firstname,othernames,surname) name FROM tblsystemuser WHERE systemtype='Teacher' AND status='active' ORDER BY firstname,surname");if($r)while($x=mysqli_fetch_assoc($r))$teachers[]=$x;$deps=array();$r=mysqli_query($con,"SELECT * FROM tbldepartment WHERE status='active' ORDER BY departmentname");if($r)while($x=mysqli_fetch_assoc($r))$deps[]=$x;
?>
<style>.dtm-select{position:relative;min-width:260px}.dtm-select button{width:100%;background:#fff!important;color:#102a43!important;border:2px solid #7893aa!important;text-align:left}.dtm-select-list{display:none;position:absolute;z-index:99;left:0;right:0;top:100%;max-height:240px;overflow:auto;background:#fff;border:2px solid #087443}.dtm-select.open .dtm-select-list{display:block}.dtm-select-list button{display:block;width:100%;background:#fff!important;color:#102a43!important;border:0!important;text-align:left}.dtm-select-list button:hover{background:#dff4e8!important}.dtm .member{display:inline-flex!important;align-items:center!important;vertical-align:middle;gap:8px}.dtm .member form{display:inline-flex!important;margin:0!important}.dtm .member .remove{margin:0!important;padding:6px 9px!important;line-height:1.1;white-space:nowrap}</style><script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.dtm select').forEach(function(s){var w=document.createElement('div'),b=document.createElement('button'),l=document.createElement('div');w.className='dtm-select';b.type='button';l.className='dtm-select-list';function u(){b.textContent=s.options[s.selectedIndex].text;}Array.prototype.forEach.call(s.options,function(o){var x=document.createElement('button');x.type='button';x.textContent=o.text;x.onclick=function(){s.value=o.value;u();w.classList.remove('open');};l.appendChild(x);});b.onclick=function(){w.classList.toggle('open');};s.parentNode.insertBefore(w,s);w.appendChild(b);w.appendChild(l);s.style.display='none';w.appendChild(s);u();});});</script>
<!doctype html><html><head><?php include('links.php');?><title>Manage Department Teams</title><style>body{background:#f4f8fb;font-family:Arial;color:#17314b}.dtm{max-width:1000px;margin:25px auto;background:#fff;padding:24px;border-radius:16px}.card{border:1px solid #dce6ee;border-radius:12px;padding:16px;margin:15px 0}.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.row select{min-width:260px;padding:10px;background:#fff;color:#102a43;border:1px solid #7893aa;border-radius:7px}.row button{padding:9px 12px;border:0;border-radius:7px;background:#087443;color:#fff}.remove{background:#b42318!important}.member{display:inline-flex;align-items:center;gap:6px;padding:7px 10px;background:#eef6f1;border-radius:20px;margin:5px}@media(max-width:600px){.dtm{margin:8px;padding:14px}.row select{width:100%}}</style></head><body><main class="dtm"><h1>Manage Department Teams</h1><p>Change HODs or remove teachers without affecting past result approvals.</p><p><a href="department-management.php">← Department setup</a></p><?php if($msg!=='')echo '<p>'.dtm($msg).'</p>';foreach($deps as $d){$members=array();$de=mysqli_real_escape_string($con,$d['departmentid']);$m=mysqli_query($con,"SELECT dt.teacherid,CONCAT_WS(' ',su.firstname,su.othernames,su.surname) name FROM tbldepartmentteacher dt LEFT JOIN tblsystemuser su ON su.userid=dt.teacherid WHERE dt.departmentid='$de' ORDER BY name");if($m)while($x=mysqli_fetch_assoc($m))$members[]=$x;?><section class="card"><h2><?php echo dtm($d['departmentname']);?></h2><form method="post" class="row"><input type="hidden" name="departmentid" value="<?php echo dtm($d['departmentid']);?>"><select name="hodid" required><?php foreach($teachers as $t){?><option value="<?php echo dtm($t['userid']);?>"<?php echo $d['hodid']===$t['userid']?' selected':'';?>><?php echo dtm($t['name']);?></option><?php }?></select><button name="change_hod">Change HOD</button></form><h3>Teachers in this department</h3><div><?php foreach($members as $teacher){?><span class="member"><?php echo dtm($teacher['name']);?><?php if($teacher['teacherid']===$d['hodid'])echo ' (HOD)';?><form method="post"><input type="hidden" name="departmentid" value="<?php echo dtm($d['departmentid']);?>"><input type="hidden" name="teacherid" value="<?php echo dtm($teacher['teacherid']);?>"><button class="remove" name="remove_teacher" onclick="return confirm('Remove this teacher from the department?');">Remove</button></form></span><?php }?></div></section><?php }?></main></body></html>
